import{a as e,i as t,r as n,t as r}from"./app-CC6Ai1Vx.js";var i=JSON.parse(`{"path":"/guide/guessgame.html","title":"猜大小","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790447772000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"cb44449b03168146c3922cb91a45aa1f8a210a5e","time":1790447772000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add economy and guess game pages, update shop with buff and scratch card"}]},"filePathRelative":"guide/guessgame.md"}`),a={name:`guessgame.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="猜大小" tabindex="-1"><a class="header-anchor" href="#猜大小"><span>猜大小</span></a></h1><p>押上金币，赌三颗骰子的和值大小。</p><h2 id="指令" tabindex="-1"><a class="header-anchor" href="#指令"><span>指令</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>猜大</code> / <code>押大</code></td><td>金额</td><td><code>.猜大 100</code></td><td>押「大」，赌和值为 11~18</td></tr><tr><td><code>猜小</code> / <code>押小</code></td><td>金额</td><td><code>.猜小 100</code></td><td>押「小」，赌和值为 3~10</td></tr></tbody></table><h2 id="玩法" tabindex="-1"><a class="header-anchor" href="#玩法"><span>玩法</span></a></h2><p>掷 3 颗六面骰，和值必然落在 3~18：</p><table><thead><tr><th>结果</th><th>和值范围</th><th>概率</th></tr></thead><tbody><tr><td>小</td><td>3 ~ 10</td><td>50%</td></tr><tr><td>大</td><td>11 ~ 18</td><td>50%</td></tr><tr><td>豹子（三颗点数相同）</td><td>——</td><td>约 2.78%（1/36）</td></tr></tbody></table><ul><li><strong>中了</strong>：投入翻倍返还。押 100 中了 → 返还 200，净赚 100</li><li><strong>没中</strong>：投入清空。押 100 没中 → 扣掉 100</li><li><strong>豹子庄家通吃</strong>：三颗点数相同时，押哪边都输</li></ul><div class="hint-container tip"><p class="hint-container-title">提示</p><p>豹子是本游戏唯一的抽水来源（期望值约 −2.78%），作用是让金币缓慢回收而非无限膨胀。</p><p>和值分布天然左右对称（3 与 18 同为 1/216，10 与 11 同为 27/216）， 所以「大」「小」概率<strong>恰好各 50%</strong>，不需要额外调概率。</p></div><h2 id="回复示例" tabindex="-1"><a class="header-anchor" href="#回复示例"><span>回复示例</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">骰子 4 2 5，和值 11 → 大</span>
<span class="line">押「大」中了！</span>
<span class="line">投入 100 → 返还 200（净赚 100）</span>
<span class="line">余额 1100 金币（今日 3/10 次）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="配置项" tabindex="-1"><a class="header-anchor" href="#配置项"><span>配置项</span></a></h2><table><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>GuessGame:MaxBet</code></td><td><code>1000</code></td><td>单次最大投入金币。<code>&lt;= 0</code> 表示不限制</td></tr><tr><td><code>GuessGame:MaxPerDay</code></td><td><code>10</code></td><td>每人每日最多对局次数（按东八区日期）。<code>&lt;= 0</code> 表示不限制</td></tr></tbody></table><h2 id="约定与限制" tabindex="-1"><a class="header-anchor" href="#约定与限制"><span>约定与限制</span></a></h2><ul><li>金额必须为正整数；超过单次上限会被拒绝</li><li>每日限次按用户 + 日期统计，用完后当日不再受理</li><li>余额不足会被拒绝，<strong>不会出现负余额</strong></li><li>对局、余额变更与流水写入在<strong>一次数据库事务</strong>内完成</li></ul>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};